/* Generated by consolidate-runtime.yml. Exact source order; no logic rewrite. */

/* ===== hotfix-v148.js ===== */
/* GRID SHIFT v1.4.8 — SHIFT onboarding + 3-move round semantics
   Goals:
   - Teach that one SHIFT round is exactly three placed pieces.
   - ① -> ② is a within-the-round objective, not something that must be hit every move.
   - Never fire a wave early. Resolve STABLE/WAVE only after the third piece.
   - If ② is touched before ①, show a brief warning but allow recovery in the same round.
   - Make the first three rounds easier by choosing closer targets from a proven two-piece route.
*/
(function(){
  'use strict';

  const VERSION=148;
  const previousTryPlace=tryPlace;
  const previousCompleteTray=completeTray;
  const previousApplyShiftRound=applyShiftRound;
  const previousRenderBoard=renderBoard;
  const previousRenderAll=renderAll;
  const previousRenderModeStat=renderModeStat;
  const previousLoadSlot=loadSlot;
  const previousNewRun=newRun;

  let early2Timer=0;

  function isShift(){return state?.mode==='SHIFT';}
  function roundIndex(){return Math.floor((Number(state?.moves)||0)/3);}
  function tutorialRound(){return isShift()&&roundIndex()<3;}
  function touch(anchor,cells){return !!(anchor&&Array.isArray(cells)&&cells.some(([x,y])=>x===anchor.x&&y===anchor.y));}
  function shuffle(a){const out=a.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}

  function syncAnchorFlags(){
    if(!isShift()||!Array.isArray(state.shiftAnchors)||state.shiftAnchors.length!==2)return;
    const step=Math.max(0,Math.min(2,Number(state.shiftStep)||0));
    state.shiftStep=step;
    state.shiftAnchors.forEach((a,i)=>{
      a.order=i+1;
      a.hit=step>i;
      a.wrong=false;
    });
  }

  /* ---------- Friendly first three rounds ---------- */
  function placementRecords(board,piece,cap=42){
    const out=[];
    if(!piece)return out;
    for(const shape of Core.modeRotations(piece,'SHIFT')){
      for(const [x,y] of Core.placements(board,shape,state.size)){
        out.push({shape,x,y,cells:shape.cells.map(([dx,dy])=>[x+dx,y+dy])});
      }
    }
    const mixed=shuffle(out);
    return mixed.length>cap?mixed.slice(0,cap):mixed;
  }

  function friendlyMission(level){
    if(!isShift()||!Array.isArray(state.tray)||state.tray.filter(Boolean).length!==3)return null;
    const ids=[0,1,2].filter(i=>state.tray[i]);
    const ideal=[2,3,4][Math.max(0,Math.min(2,level))]||3;
    const candidates=[];
    let nodes=0;

    for(const firstIdx of shuffle(ids)){
      for(const first of placementRecords(state.board,state.tray[firstIdx],38)){
        if(++nodes>1900)break;
        const sim1=Core.simulatePlace(state.board,first.shape,first.x,first.y,'SHIFT',state.size);
        if(!sim1)continue;
        for(const secondIdx of shuffle(ids.filter(i=>i!==firstIdx))){
          for(const second of placementRecords(sim1.board,state.tray[secondIdx],34)){
            if(++nodes>1900)break;
            for(const [x1,y1] of first.cells){
              for(const [x2,y2] of second.cells){
                if(x1===x2&&y1===y2)continue;
                const dist=Math.abs(x1-x2)+Math.abs(y1-y2);
                if(dist<1||dist>6)continue;
                const edge1=Math.min(x1,y1,state.size-1-x1,state.size-1-y1);
                const edge2=Math.min(x2,y2,state.size-1-x2,state.size-1-y2);
                const central=Math.min(edge1,2)+Math.min(edge2,2);
                const score=90-Math.abs(dist-ideal)*15+central*3+Math.random()*8;
                candidates.push({a1:{x:x1,y:y1,order:1,hit:false},a2:{x:x2,y:y2,order:2,hit:false},score});
                if(candidates.length>=80)break;
              }
              if(candidates.length>=80)break;
            }
            if(candidates.length>=80||nodes>1900)break;
          }
          if(candidates.length>=80||nodes>1900)break;
        }
        if(candidates.length>=80||nodes>1900)break;
      }
      if(candidates.length>=80||nodes>1900)break;
    }
    if(!candidates.length)return null;
    candidates.sort((a,b)=>b.score-a.score);
    const top=candidates.slice(0,Math.min(10,candidates.length));
    const pick=top[Math.floor(Math.random()*top.length)];
    return [pick.a1,pick.a2];
  }

  function maybeFriendlyMission(){
    if(!tutorialRound()||state.shiftRoundResolved||Number(state.shiftMissionMoves)>0)return;
    const m=friendlyMission(roundIndex());
    if(!m)return;
    state.shiftAnchors=m;
    state.shiftStep=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    syncAnchorFlags();
  }

  /* ---------- Round guide ---------- */
  function ensureGuide(){
    let guide=document.getElementById('shiftGuideV148');
    const shell=document.querySelector('.game-shell');
    const boardWrap=document.querySelector('.board-wrap');
    if(!shell||!boardWrap)return null;
    if(!guide){
      guide=document.createElement('div');
      guide.id='shiftGuideV148';
      guide.className='shift-guide-v148';
      guide.innerHTML=''
        +'<div class="shift-guide-main-v148">'
        +'<span class="shift-guide-label-v148"></span>'
        +'<span class="shift-pips-v148"><i></i><i></i><i></i></span>'
        +'<span class="shift-goal-v148"><b class="g1">①</b><em>→</em><b class="g2">②</b></span>'
        +'</div>'
        +'<div class="shift-wave-v148"><small></small><b></b></div>';
    }
    const modeBadge=document.getElementById('modeBadgeV143');
    if(modeBadge&&modeBadge.nextSibling!==guide)modeBadge.after(guide);
    else if(!guide.isConnected)shell.insertBefore(guide,boardWrap);
    return guide;
  }

  function patternInfo(){
    const p=String(state?.shiftPattern||'');
    if(p==='V_DOWN')return {axis:'COLS',glyph:'↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑'};
    if(p==='H_LEFT')return {axis:'ROWS',glyph:'← → ← → ← → ← → ← →'};
    if(p==='H_RIGHT')return {axis:'ROWS',glyph:'→ ← → ← → ← → ← → ←'};
    return {axis:'COLS',glyph:'↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓'};
  }

  function syncGuide(){
    const guide=ensureGuide();
    if(!guide)return;
    const active=isShift();
    guide.hidden=!active;
    if(!active)return;

    const intro=tutorialRound();
    const placed=Math.max(0,Math.min(3,Number(state.shiftMissionMoves)||0));
    const step=Math.max(0,Math.min(2,Number(state.shiftStep)||0));
    guide.classList.toggle('intro-v148',intro);
    guide.querySelector('.shift-guide-label-v148').textContent=intro?'3 PIECES = 1 ROUND':'ROUND';
    guide.querySelectorAll('.shift-pips-v148 i').forEach((p,i)=>p.classList.toggle('spent',i<placed));
    const g1=guide.querySelector('.shift-goal-v148 .g1'),g2=guide.querySelector('.shift-goal-v148 .g2');
    g1.classList.toggle('done',step>=1);g1.classList.toggle('current',step===0);
    g2.classList.toggle('done',step>=2);g2.classList.toggle('current',step===1);
    const info=patternInfo();
    guide.querySelector('.shift-wave-v148 small').textContent=intro?'IF MISSED':'MISS';
    guide.querySelector('.shift-wave-v148 b').textContent=`${info.axis}  ${info.glyph}`;
  }

  function flashEarlyTwo(){
    if(!isShift())return;
    state.shiftEarly2V148=true;
    clearTimeout(early2Timer);
    early2Timer=setTimeout(()=>{
      if(state){state.shiftEarly2V148=false;if(isShift())renderBoard();}
    },650);
  }

  function advanceMissionV148(cells){
    if(!isShift()||state.shiftRoundResolved||!Array.isArray(state.shiftAnchors)||state.shiftAnchors.length!==2)return '';
    syncAnchorFlags();
    const a1=state.shiftAnchors[0],a2=state.shiftAnchors[1];
    const h1=touch(a1,cells),h2=touch(a2,cells);

    if(state.shiftStep===0){
      if(h1){
        state.shiftStep=1;
        syncAnchorFlags();
        requestSound('anchorStep',1);
        announce('① SET  •  NEXT ②',true);
        return 'one';
      }
      if(h2){
        flashEarlyTwo();
        requestSound('sequenceBad');
        announce('② AFTER ①',false);
        return 'early2';
      }
    }else if(state.shiftStep===1&&h2){
      state.shiftStep=2;
      syncAnchorFlags();
      requestSound('anchorStep',2);
      announce('② SET  •  FINISH ROUND',true);
      return 'two';
    }
    return '';
  }

  /* Resolve only at the end of the three-piece tray. The v1.3.6 resolver still
     owns the actual wave/stabilize mechanics; we only change WHEN it is invoked. */
  applyShiftRound=function(){
    if(!isShift())return previousApplyShiftRound();
    if(state.shiftRoundResolved)return;
    state.shiftMissionFailed=state.shiftStep<2;
    return previousApplyShiftRound();
  };

  completeTray=function(){
    if(!isShift())return previousCompleteTray();
    const out=previousCompleteTray();
    if(!state.gameOver){
      state.shiftOnboardingVersion=VERSION;
      state.shiftEarly2V148=false;
      maybeFriendlyMission();
      syncGuide();
    }
    return out;
  };

  /* Single authoritative SHIFT placement path for v1.4.8. */
  tryPlace=function(idx,x,y){
    if(!isShift())return previousTryPlace(idx,x,y);
    if(state.gameOver||resolving)return false;

    const shape=state.tray[idx];
    if(!shape||!Core.canPlace(state.board,shape,x,y,state.size))return false;
    const sim=Core.simulatePlace(state.board,shape,x,y,'SHIFT',state.size);
    if(!sim)return false;

    state.board=sim.board;
    state.tray[idx]=null;
    state.moves++;
    state.score+=shape.cells.length;
    state.lastPlaced=sim.placed.map(c=>c.slice());
    queueFx('placed',sim.placed);
    beep('place',shape.cells.length);

    let totalUnits=0,totalCells=0;
    sim.waves.forEach((wave,i)=>{
      totalUnits+=wave.units;totalCells+=wave.cells.length;queueFx('burst',{cells:wave.cells,wave:i});
    });
    if(totalUnits>0){
      state.trayHadClear=true;
      const gain=scoreClear(totalUnits,totalCells,Math.max(0,sim.waves.length-1));
      state.score+=gain;
      announce(totalUnits>1?`${totalUnits} CLEAR  +${gain}`:`CLEAR  +${gain}`,totalUnits>1);
      beep(totalUnits>1?'multi':'clear');
    }

    if(!state.shiftRoundResolved){
      state.shiftMissionMoves=Math.max(0,Number(state.shiftMissionMoves)||0)+1;
      advanceMissionV148(sim.placed);
      /* Deliberately no wave/stabilize here. Even a mathematically failed round
         remains playable until piece three, so first-time players learn the rhythm. */
    }

    const trayFinished=state.tray.every(p=>p===null);
    if(trayFinished)completeTray();

    if(state.score>state.best)state.best=state.score;
    selectedPiece=null;previewAnchor=null;
    renderAll();scheduleSave();
    if(!state.gameOver&&!state.tray.some(p=>p&&Core.hasModePlacement(state.board,p,state.size,state.mode)))endGame('NO MOVES');
    return true;
  };

  renderBoard=function(){
    const out=previousRenderBoard();
    if(isShift()&&!state.shiftRoundResolved&&state.shiftEarly2V148&&Array.isArray(state.shiftAnchors)){
      const a2=state.shiftAnchors[1];
      cellEls[a2?.y]?.[a2?.x]?.classList.add('shift-early2-v148');
    }
    return out;
  };

  renderModeStat=function(){
    previousRenderModeStat();
    if(!isShift())return;
    const step=Math.max(0,Math.min(2,Number(state.shiftStep)||0));
    modeStatEl.textContent=step===0?'①  →  ②':step===1?'① ✓  →  ②':'① ✓   ② ✓';
    modeStatEl.classList.add('visible');
  };

  renderAll=function(){
    const out=previousRenderAll();
    syncGuide();
    return out;
  };

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(isShift()&&!state.gameOver){
      /* Do not move targets in the middle of an existing three-piece round. */
      if(Number(state.shiftMissionMoves)===0)maybeFriendlyMission();
      state.shiftOnboardingVersion=VERSION;
      renderAll();scheduleSave(true);
    }else syncGuide();
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(isShift()&&!state.gameOver){
      state.shiftOnboardingVersion=VERSION;
      state.shiftMissionMoves=0;
      state.shiftEarly2V148=false;
      maybeFriendlyMission();
      renderAll();scheduleSave(true);
    }
    return out;
  };

  queueMicrotask(()=>{
    try{
      if(isShift()&&!state.gameOver){
        if(Number(state.shiftMissionMoves)===0)maybeFriendlyMission();
        state.shiftOnboardingVersion=VERSION;
        renderAll();scheduleSave(true);
      }else syncGuide();
    }catch(_){ }
  });
})();


/* ===== hotfix-v149.js ===== */
/* GRID SHIFT v1.4.9 — SHIFT simplified to a self-explanatory three-move rhythm.
   Rule:
   - Every tray of 3 pieces is one round.
   - If the player clears any normal row/column during those 3 placements, the round is STABLE and no shift occurs.
   - Otherwise, after piece 3 the board performs the already-established alternating row/column wave.
   - ①/② targets are retired completely.
*/
(function(){
  'use strict';

  const VERSION=149;
  const PATTERNS=['V_UP','V_DOWN','H_LEFT','H_RIGHT'];
  const PATTERN_TEXT={
    V_UP:'↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓',
    V_DOWN:'↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑',
    H_LEFT:'← → ← → ← → ← → ← →',
    H_RIGHT:'→ ← → ← → ← → ← → ←'
  };

  const previousTryPlace=tryPlace;
  const previousCompleteTray=completeTray;
  const previousRenderBoard=renderBoard;
  const previousRenderAll=renderAll;
  const previousRenderModeStat=renderModeStat;
  const previousLoadSlot=loadSlot;
  const previousNewRun=newRun;
  const previousModeDemoHTML=modeDemoHTML;

  function isShift(){return state?.mode==='SHIFT';}

  function randomPattern(prev=''){
    const pool=PATTERNS.filter(p=>p!==prev);
    const src=pool.length?pool:PATTERNS;
    return src[Math.floor(Math.random()*src.length)];
  }

  function waveShift(board,size,pattern){
    const out=Core.emptyBoard(size);
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const v=board[y][x];if(!v)continue;
      let xx=x,yy=y;
      if(pattern==='V_UP'||pattern==='V_DOWN'){
        const firstUp=pattern==='V_UP';
        const up=(x%2===0)?firstUp:!firstUp;
        yy=(y+(up?-1:1)+size)%size;
      }else{
        const firstLeft=pattern==='H_LEFT';
        const left=(y%2===0)?firstLeft:!firstLeft;
        xx=(x+(left?-1:1)+size)%size;
      }
      out[yy][xx]=v;
    }
    return out;
  }

  function clearLegacyMissionState(){
    if(!state)return;
    state.shiftAnchors=[];
    state.shiftAnchor=null;
    state.shiftAnchorHit=false;
    state.shiftStep=0;
    state.shiftMissionMoves=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    state.shiftEarly2V148=false;
  }

  function startRound(newPattern=true){
    if(!isShift())return;
    state.shiftRulesVersion=VERSION;
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    if(newPattern||!PATTERNS.includes(state.shiftPattern))state.shiftPattern=randomPattern(state.shiftPattern);
    clearLegacyMissionState();
  }

  function migrateIfNeeded(){
    if(!isShift()||state.gameOver)return;
    if(state.shiftRulesVersion===VERSION){
      if(!PATTERNS.includes(state.shiftPattern))state.shiftPattern=randomPattern('');
      state.shiftRoundMovesV149=Math.max(0,Math.min(2,Number(state.shiftRoundMovesV149)||0));
      state.shiftRoundClearedV149=!!state.shiftRoundClearedV149;
      clearLegacyMissionState();
      return;
    }
    /* Old SHIFT saves contain ①/② mission state that no longer has meaning. Keep
       board/score/best, but begin one clean three-piece round under the new rule. */
    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    startRound(true);
  }

  function clearLegacyTargetClasses(){
    for(const row of cellEls||[])for(const c of row||[]){
      if(!c)continue;
      c.classList.remove(
        'shift-anchor-v131','shift-anchor-v132','anchor-secured-v131',
        'shift-order-v133','shift-order-v134',
        'order-current-v133','order-current-v134','order-locked-v133','order-locked-v134',
        'order-done-v133','order-done-v134','order-failed-v133','order-failed-v134',
        'shift-early2-v148'
      );
      delete c.dataset.anchorNumber;
      delete c.dataset.orderGlyph;
      delete c.dataset.anchor;
    }
  }

  function patternLabel(){
    const p=PATTERNS.includes(state?.shiftPattern)?state.shiftPattern:'V_UP';
    const axis=(p==='V_UP'||p==='V_DOWN')?'COLS':'ROWS';
    return {axis,glyph:PATTERN_TEXT[p]||PATTERN_TEXT.V_UP};
  }

  function ensureGuide(){
    let guide=document.getElementById('shiftGuideV149');
    const shell=document.querySelector('.game-shell');
    const boardWrap=document.querySelector('.board-wrap');
    if(!shell||!boardWrap)return null;
    if(!guide){
      guide=document.createElement('div');
      guide.id='shiftGuideV149';
      guide.className='shift-guide-v149';
      guide.innerHTML='<div class="shift-rule-v149"><span class="shift-pips-v149"><i></i><i></i><i></i></span><b class="shift-arrow-v149">→</b><strong>SHIFT</strong><em class="shift-stable-v149">✓ STABLE</em></div><div class="shift-direction-v149"></div>';
    }
    const old=document.getElementById('shiftGuideV148');if(old)old.hidden=true;
    const badge=document.getElementById('modeBadgeV143');
    if(badge&&badge.nextSibling!==guide)badge.after(guide);
    else if(!guide.isConnected)shell.insertBefore(guide,boardWrap);
    return guide;
  }

  function syncGuide(){
    const guide=ensureGuide();if(!guide)return;
    guide.hidden=!isShift();
    if(!isShift())return;
    const moves=Math.max(0,Math.min(3,Number(state.shiftRoundMovesV149)||0));
    const stable=!!state.shiftRoundClearedV149;
    guide.classList.toggle('stable-v149',stable);
    guide.querySelectorAll('.shift-pips-v149 i').forEach((p,i)=>p.classList.toggle('spent',i<moves));
    const info=patternLabel();
    guide.querySelector('.shift-direction-v149').textContent=stable?'NO SHIFT THIS ROUND':`${info.axis}  ${info.glyph}`;
  }

  function fireWave(){
    const pattern=PATTERNS.includes(state.shiftPattern)?state.shiftPattern:'V_UP';
    state.board=waveShift(state.board,state.size,pattern);
    boardEl.dataset.waveFx=pattern;
    boardEl.classList.remove('wave-shift-v131');void boardEl.offsetWidth;boardEl.classList.add('wave-shift-v131');
    setTimeout(()=>{boardEl.classList.remove('wave-shift-v131');delete boardEl.dataset.waveFx;},440);
    requestSound('shift');

    const clear=Core.scanClears(state.board,state.size,'CLASSIC');
    if(clear.units){
      Core.clearCells(state.board,clear.cells);
      state.trayHadClear=true;
      const gain=scoreClear(clear.units,clear.cells.length,0)+60;
      state.score+=gain;
      queueFx('burst',{cells:clear.cells,wave:0});
      announce(`SHIFT CLEAR  +${gain}`,true);
    }else announce('SHIFT',false);
  }

  function finishShiftRound(){
    if(state.shiftRoundClearedV149){
      state.shiftRoundResultV149='STABLE';
      requestSound('sequenceWin');
      boardEl.classList.remove('shift-stabilized-v131');void boardEl.offsetWidth;boardEl.classList.add('shift-stabilized-v131');
      setTimeout(()=>boardEl.classList.remove('shift-stabilized-v131'),440);
      announce('STABLE  •  NO SHIFT',true);
    }else{
      state.shiftRoundResultV149='SHIFT';
      fireWave();
    }
  }

  completeTray=function(){
    if(!isShift())return previousCompleteTray();

    finishShiftRound();

    if(state.trayHadClear){
      state.chain++;
      const bonus=state.chain>=2?25*state.chain:0;
      if(bonus){
        state.score+=bonus;
        if(state.chain===3||state.chain===5||state.chain%10===0){announce(`CHAIN ${state.chain}  +${bonus}`,true);beep('chain');queueFx('chain',state.chain);}
      }
    }else state.chain=0;
    state.trayHadClear=false;

    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    startRound(true);
  };

  tryPlace=function(idx,x,y){
    if(!isShift())return previousTryPlace(idx,x,y);
    if(state.gameOver||resolving)return false;

    const shape=state.tray[idx];
    if(!shape||!Core.canPlace(state.board,shape,x,y,state.size))return false;
    const sim=Core.simulatePlace(state.board,shape,x,y,'SHIFT',state.size);
    if(!sim)return false;

    state.board=sim.board;
    state.tray[idx]=null;
    state.moves++;
    state.shiftRoundMovesV149=Math.min(3,(Number(state.shiftRoundMovesV149)||0)+1);
    state.score+=shape.cells.length;
    state.lastPlaced=sim.placed.map(c=>c.slice());
    queueFx('placed',sim.placed);
    beep('place',shape.cells.length);

    let totalUnits=0,totalCells=0;
    sim.waves.forEach((wave,i)=>{
      totalUnits+=wave.units;totalCells+=wave.cells.length;queueFx('burst',{cells:wave.cells,wave:i});
    });
    if(totalUnits>0){
      state.shiftRoundClearedV149=true;
      state.trayHadClear=true;
      const gain=scoreClear(totalUnits,totalCells,Math.max(0,sim.waves.length-1));
      state.score+=gain;
      announce(totalUnits>1?`${totalUnits} CLEAR  +${gain}`:`CLEAR  +${gain}`,totalUnits>1);
      beep(totalUnits>1?'multi':'clear');
    }

    const trayFinished=state.tray.every(p=>p===null);
    if(trayFinished)completeTray();

    if(state.score>state.best)state.best=state.score;
    selectedPiece=null;previewAnchor=null;
    renderAll();scheduleSave();
    if(!state.gameOver&&!state.tray.some(p=>p&&Core.hasModePlacement(state.board,p,state.size,state.mode)))endGame('NO MOVES');
    return true;
  };

  renderBoard=function(){
    const out=previousRenderBoard();
    if(isShift())clearLegacyTargetClasses();
    return out;
  };

  renderModeStat=function(){
    previousRenderModeStat();
    if(!isShift())return;
    modeStatEl.textContent='';
    modeStatEl.classList.remove('visible','urgent');
  };

  renderAll=function(){
    const out=previousRenderAll();
    if(isShift())clearLegacyTargetClasses();
    syncGuide();
    return out;
  };

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(isShift()&&!state.gameOver){
      migrateIfNeeded();
      renderAll();scheduleSave(true);
    }else syncGuide();
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(isShift()&&!state.gameOver){
      startRound(true);
      renderAll();scheduleSave(true);
    }
    return out;
  };

  /* Update the selector animation too: no more ①/②. It now shows three moves
     counting down into the alternating wave, which is the actual game rule. */
  modeDemoHTML=function(id){
    if(id!=='SHIFT')return previousModeDemoHTML(id);
    let cells='';
    cells+=miniCell(0,1,'md-cyan v149-shift-row r1');
    cells+=miniCell(1,1,'md-cyan v149-shift-row r1');
    cells+=miniCell(3,1,'md-purple v149-shift-row r1');
    cells+=miniCell(1,3,'md-green v149-shift-row r2');
    cells+=miniCell(2,3,'md-green v149-shift-row r2');
    cells+=miniCell(4,3,'md-gold v149-shift-row r2');
    return `<div class="mode-demo mode-demo-v147 demo-shift-v149"><div class="mini-board">${cells}<div class="v149-demo-count"><i></i><i></i><i></i><b>→</b><strong>⇄</strong></div><em class="v149-demo-a a1">→</em><em class="v149-demo-a a2">←</em></div></div>`;
  };

  queueMicrotask(()=>{
    try{
      buildMenu();renderMenu();
      if(isShift()&&!state.gameOver){migrateIfNeeded();renderAll();scheduleSave(true);}else syncGuide();
    }catch(_){ }
  });
})();


/* ===== hotfix-v150.js ===== */
/* GRID SHIFT v1.5.0 — SHIFT: the final piece must read as the trigger, not as spare time.
   - At 2/3 moves with no clear yet, the pip counter is replaced by NEXT MOVE -> SHIFT.
   - If the round is already stable, the warning disappears and STABLE remains.
   - While dragging the final piece, a placement that would clear a line previews CLEAR -> STABLE.
*/
(function(){
  'use strict';

  const previousRenderAll=renderAll;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;

  function isShift(){return state?.mode==='SHIFT'&&state?.shiftRulesVersion===149;}

  function guide(){return document.getElementById('shiftGuideV149');}

  function ensureCue(){
    const g=guide();if(!g)return null;
    let cue=g.querySelector('.shift-last-v150');
    if(!cue){
      cue=document.createElement('span');
      cue.className='shift-last-v150';
      const rule=g.querySelector('.shift-rule-v149');
      if(rule)rule.appendChild(cue);
    }
    return cue;
  }

  function syncCue(previewStable=false){
    const g=guide();
    if(!g)return;
    const active=isShift();
    g.classList.remove('last-move-v150','preview-stable-v150');
    boardEl?.classList.remove('shift-next-v150','shift-preview-stable-v150');
    if(!active)return;

    const moves=Math.max(0,Math.min(3,Number(state.shiftRoundMovesV149)||0));
    const stable=!!state.shiftRoundClearedV149;
    const last=!stable&&moves===2;
    const cue=ensureCue();

    if(last){
      g.classList.add('last-move-v150');
      boardEl?.classList.add('shift-next-v150');
      if(cue)cue.textContent='NEXT MOVE  →  SHIFT';
      if(previewStable){
        g.classList.add('preview-stable-v150');
        boardEl?.classList.remove('shift-next-v150');
        boardEl?.classList.add('shift-preview-stable-v150');
        if(cue)cue.textContent='CLEAR HERE  →  STABLE ✓';
      }
    }else if(cue){
      cue.textContent='';
    }
  }

  function previewWillStabilize(){
    if(!isShift()||state.shiftRoundClearedV149||Number(state.shiftRoundMovesV149)!==2)return false;
    if(selectedPiece===null||!previewAnchor)return false;
    const shape=drag?.shape||state.tray?.[selectedPiece];
    if(!shape||!Core.canPlace(state.board,shape,previewAnchor.x,previewAnchor.y,state.size))return false;
    const sim=Core.simulatePlace(state.board,shape,previewAnchor.x,previewAnchor.y,'SHIFT',state.size);
    return !!(sim&&Array.isArray(sim.waves)&&sim.waves.length);
  }

  updatePreview=function(){
    const out=previousUpdatePreview();
    syncCue(previewWillStabilize());
    return out;
  };

  clearPreview=function(){
    const out=previousClearPreview();
    syncCue(false);
    return out;
  };

  renderAll=function(){
    const out=previousRenderAll();
    syncCue(false);
    return out;
  };

  queueMicrotask(()=>{try{syncCue(false);}catch(_){ }});
})();


/* ===== hotfix-v151.js ===== */
/* GRID SHIFT v1.5.1 — SHIFT never awards an accidental clear.
   The player's placement is the only way to earn STABLE / a line clear.
   Before an unstable round shifts, test the available wave patterns and use one
   that does not leave a completed row/column. During the final drag, show the
   exact safe direction that will be used so the forecast remains truthful.
*/
(function(){
  'use strict';

  const ALT=['V_UP','V_DOWN','H_LEFT','H_RIGHT'];
  const LABEL={
    V_UP:{axis:'COLS',glyph:'↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓'},
    V_DOWN:{axis:'COLS',glyph:'↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑'},
    H_LEFT:{axis:'ROWS',glyph:'← → ← → ← → ← → ← →'},
    H_RIGHT:{axis:'ROWS',glyph:'→ ← → ← → ← → ← → ←'},
    V_ALL_UP:{axis:'COLS',glyph:'↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑'},
    V_ALL_DOWN:{axis:'COLS',glyph:'↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓'},
    H_ALL_LEFT:{axis:'ROWS',glyph:'← ← ← ← ← ← ← ← ← ←'},
    H_ALL_RIGHT:{axis:'ROWS',glyph:'→ → → → → → → → → →'}
  };

  const previousCompleteTray=completeTray;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;

  function isShift(){return state?.mode==='SHIFT'&&state?.shiftRulesVersion===149;}

  function shifted(board,size,plan){
    const out=Core.emptyBoard(size);
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const v=board[y][x];if(!v)continue;
      let xx=x,yy=y;
      if(plan==='V_UP'||plan==='V_DOWN'){
        const firstUp=plan==='V_UP';
        const up=(x%2===0)?firstUp:!firstUp;
        yy=(y+(up?-1:1)+size)%size;
      }else if(plan==='H_LEFT'||plan==='H_RIGHT'){
        const firstLeft=plan==='H_LEFT';
        const left=(y%2===0)?firstLeft:!firstLeft;
        xx=(x+(left?-1:1)+size)%size;
      }else if(plan==='V_ALL_UP') yy=(y-1+size)%size;
      else if(plan==='V_ALL_DOWN') yy=(y+1)%size;
      else if(plan==='H_ALL_LEFT') xx=(x-1+size)%size;
      else if(plan==='H_ALL_RIGHT') xx=(x+1)%size;
      out[yy][xx]=v;
    }
    return out;
  }

  function hasFullLine(board,size){
    for(let y=0;y<size;y++){
      let full=true;for(let x=0;x<size;x++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    for(let x=0;x<size;x++){
      let full=true;for(let y=0;y<size;y++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    return false;
  }

  function candidateOrder(preferred){
    const p=ALT.includes(preferred)?preferred:'V_UP';
    const sameAxis=p.startsWith('V')?(p==='V_UP'?'V_DOWN':'V_UP'):(p==='H_LEFT'?'H_RIGHT':'H_LEFT');
    const other=p.startsWith('V')?['H_LEFT','H_RIGHT']:['V_UP','V_DOWN'];
    const fallback={V_UP:'V_ALL_UP',V_DOWN:'V_ALL_DOWN',H_LEFT:'H_ALL_LEFT',H_RIGHT:'H_ALL_RIGHT'}[p];
    const fallbackOpp={V_UP:'V_ALL_DOWN',V_DOWN:'V_ALL_UP',H_LEFT:'H_ALL_RIGHT',H_RIGHT:'H_ALL_LEFT'}[p];
    return [p,sameAxis,...other,fallback,fallbackOpp];
  }

  function chooseSafePlan(board,preferred){
    for(const plan of candidateOrder(preferred)){
      const next=shifted(board,state.size,plan);
      if(!hasFullLine(next,state.size))return {plan,board:next};
    }
    /* Uniform whole-board translations preserve line fullness. On a valid SHIFT
       board this branch is only a corruption safeguard. */
    const plan='V_ALL_UP';
    return {plan,board:shifted(board,state.size,plan)};
  }

  function label(plan){return LABEL[plan]||LABEL.V_UP;}
  function guideDirection(){return document.querySelector('#shiftGuideV149 .shift-direction-v149');}
  function showPlan(plan,stable=false){
    const el=guideDirection();if(!el||!isShift())return;
    if(stable){el.textContent='NO SHIFT THIS ROUND';return;}
    const l=label(plan||state.shiftPattern);
    el.textContent=`${l.axis}  ${l.glyph}`;
  }

  function previewResult(){
    if(!isShift()||state.shiftRoundClearedV149||Number(state.shiftRoundMovesV149)!==2)return null;
    if(selectedPiece===null||!previewAnchor)return null;
    const shape=drag?.shape||state.tray?.[selectedPiece];
    if(!shape||!Core.canPlace(state.board,shape,previewAnchor.x,previewAnchor.y,state.size))return null;
    const sim=Core.simulatePlace(state.board,shape,previewAnchor.x,previewAnchor.y,'SHIFT',state.size);
    if(!sim)return null;
    if(Array.isArray(sim.waves)&&sim.waves.length)return {stable:true,plan:null};
    return {stable:false,...chooseSafePlan(sim.board,state.shiftPattern)};
  }

  updatePreview=function(){
    const out=previousUpdatePreview();
    const r=previewResult();
    if(r)showPlan(r.plan,r.stable);
    return out;
  };

  clearPreview=function(){
    const out=previousClearPreview();
    if(isShift())showPlan(state.shiftPattern,!!state.shiftRoundClearedV149);
    return out;
  };

  function nextPattern(prev){
    const pool=ALT.filter(p=>p!==prev);
    return pool[Math.floor(Math.random()*pool.length)]||'V_UP';
  }

  function resetRound(next){
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    state.shiftSafeVersion=151;
    state.shiftPattern=next;
    state.shiftAnchors=[];
    state.shiftAnchor=null;
    state.shiftAnchorHit=false;
    state.shiftStep=0;
    state.shiftMissionMoves=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    state.shiftEarly2V148=false;
  }

  /* Replace only the SHIFT round resolver. v1.4.9 still owns placement, scoring,
     and STABLE detection; this removes its post-wave scan that could reward luck. */
  completeTray=function(){
    if(!isShift())return previousCompleteTray();

    const preferred=ALT.includes(state.shiftPattern)?state.shiftPattern:'V_UP';

    if(state.shiftRoundClearedV149){
      state.shiftRoundResultV149='STABLE';
      requestSound('sequenceWin');
      boardEl.classList.remove('shift-stabilized-v131');void boardEl.offsetWidth;boardEl.classList.add('shift-stabilized-v131');
      setTimeout(()=>boardEl.classList.remove('shift-stabilized-v131'),440);
      announce('STABLE  •  NO SHIFT',true);
    }else{
      const safe=chooseSafePlan(state.board,preferred);
      state.shiftRoundResultV149='SHIFT';
      state.shiftLastAppliedV151=safe.plan;
      state.board=safe.board;
      boardEl.dataset.waveFx=safe.plan;
      boardEl.classList.remove('wave-shift-v131');void boardEl.offsetWidth;boardEl.classList.add('wave-shift-v131');
      setTimeout(()=>{boardEl.classList.remove('wave-shift-v131');delete boardEl.dataset.waveFx;},440);
      requestSound('shift');
      announce('SHIFT',false);
      /* Intentionally NO line scan here. chooseSafePlan guarantees the shift
         itself cannot create a completed row/column. */
    }

    if(state.trayHadClear){
      state.chain++;
      const bonus=state.chain>=2?25*state.chain:0;
      if(bonus){
        state.score+=bonus;
        if(state.chain===3||state.chain===5||state.chain%10===0){announce(`CHAIN ${state.chain}  +${bonus}`,true);beep('chain');queueFx('chain',state.chain);}
      }
    }else state.chain=0;
    state.trayHadClear=false;

    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    resetRound(nextPattern(preferred));
  };

  queueMicrotask(()=>{try{if(isShift())showPlan(state.shiftPattern,!!state.shiftRoundClearedV149);}catch(_){ }});
})();


/* ===== hotfix-v152.js ===== */
/* GRID SHIFT v1.5.2 — SHIFT becomes a real board transformation.
   - An unstable 3-piece round no longer nudges cells by one space.
   - Alternating rows/columns PACK completely toward their forecast arrows.
   - A plan that would create a full line by luck is rejected.
   - Extremely dense edge cases fall back to a safe one-cell whole-board move.
   - The selector preview demonstrates packing, not a one-cell nudge.
*/
(function(){
  'use strict';

  const VERSION=152;
  const ALT=['V_UP','V_DOWN','H_LEFT','H_RIGHT'];
  const LABEL={
    V_UP:{axis:'COLS',glyph:'↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓'},
    V_DOWN:{axis:'COLS',glyph:'↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑ ↓ ↑'},
    H_LEFT:{axis:'ROWS',glyph:'← → ← → ← → ← → ← →'},
    H_RIGHT:{axis:'ROWS',glyph:'→ ← → ← → ← → ← → ←'},
    V_ALL_UP:{axis:'COLS',glyph:'↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑ ↑'},
    V_ALL_DOWN:{axis:'COLS',glyph:'↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓ ↓'},
    H_ALL_LEFT:{axis:'ROWS',glyph:'← ← ← ← ← ← ← ← ← ←'},
    H_ALL_RIGHT:{axis:'ROWS',glyph:'→ → → → → → → → → →'}
  };

  const previousCompleteTray=completeTray;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;
  const previousRenderAll=renderAll;
  const previousModeDemoHTML=modeDemoHTML;
  let pendingPackFx=null;

  function isShift(){return state?.mode==='SHIFT'&&state?.shiftRulesVersion===149;}

  function empty(size){return Core.emptyBoard(size);}

  /* Return both the packed board and source->target movement records so the
     rendered cells can visibly slide the full distance instead of merely flashing. */
  function packBoard(board,size,plan){
    const out=empty(size),moves=[];

    if(plan==='V_UP'||plan==='V_DOWN'){
      const firstUp=plan==='V_UP';
      for(let x=0;x<size;x++){
        const up=(x%2===0)?firstUp:!firstUp;
        const items=[];
        for(let y=0;y<size;y++)if(board[y][x])items.push({v:board[y][x],sx:x,sy:y});
        const start=up?0:size-items.length;
        items.forEach((it,i)=>{
          const ty=start+i;out[ty][x]=it.v;
          moves.push({sx:it.sx,sy:it.sy,tx:x,ty});
        });
      }
      return {board:out,moves,plan,kind:'pack'};
    }

    if(plan==='H_LEFT'||plan==='H_RIGHT'){
      const firstLeft=plan==='H_LEFT';
      for(let y=0;y<size;y++){
        const left=(y%2===0)?firstLeft:!firstLeft;
        const items=[];
        for(let x=0;x<size;x++)if(board[y][x])items.push({v:board[y][x],sx:x,sy:y});
        const start=left?0:size-items.length;
        items.forEach((it,i)=>{
          const tx=start+i;out[y][tx]=it.v;
          moves.push({sx:it.sx,sy:it.sy,tx,ty:y});
        });
      }
      return {board:out,moves,plan,kind:'pack'};
    }

    return null;
  }

  /* Rare safety fallback. Uniform translation cannot create a new full row/column
     if none existed beforehand, because it preserves the line occupancy exactly. */
  function uniformBoard(board,size,plan){
    const out=empty(size),moves=[];
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const v=board[y][x];if(!v)continue;
      let tx=x,ty=y;
      if(plan==='V_ALL_UP')ty=(y-1+size)%size;
      else if(plan==='V_ALL_DOWN')ty=(y+1)%size;
      else if(plan==='H_ALL_LEFT')tx=(x-1+size)%size;
      else if(plan==='H_ALL_RIGHT')tx=(x+1)%size;
      out[ty][tx]=v;moves.push({sx:x,sy:y,tx,ty});
    }
    return {board:out,moves,plan,kind:'fallback'};
  }

  function hasFullLine(board,size){
    for(let y=0;y<size;y++){
      let full=true;for(let x=0;x<size;x++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    for(let x=0;x<size;x++){
      let full=true;for(let y=0;y<size;y++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    return false;
  }

  function candidateOrder(preferred){
    const p=ALT.includes(preferred)?preferred:'V_UP';
    const opposite=p==='V_UP'?'V_DOWN':p==='V_DOWN'?'V_UP':p==='H_LEFT'?'H_RIGHT':'H_LEFT';
    const other=p.startsWith('V')?['H_LEFT','H_RIGHT']:['V_UP','V_DOWN'];
    return [p,opposite,...other];
  }

  function fallbackPlan(preferred){
    if(preferred==='V_DOWN')return 'V_ALL_DOWN';
    if(preferred==='H_LEFT')return 'H_ALL_LEFT';
    if(preferred==='H_RIGHT')return 'H_ALL_RIGHT';
    return 'V_ALL_UP';
  }

  function choosePack(board,preferred){
    for(const plan of candidateOrder(preferred)){
      const result=packBoard(board,state.size,plan);
      if(result&&!hasFullLine(result.board,state.size))return result;
    }
    return uniformBoard(board,state.size,fallbackPlan(preferred));
  }

  function label(plan){return LABEL[plan]||LABEL.V_UP;}
  function guideDirection(){return document.querySelector('#shiftGuideV149 .shift-direction-v149');}
  function showPlan(plan,stable=false){
    const el=guideDirection();if(!el||!isShift())return;
    if(stable){el.textContent='NO SHIFT THIS ROUND';return;}
    const l=label(plan||state.shiftPattern);
    el.textContent=`${l.axis}  ${l.glyph}`;
  }

  function previewResult(){
    if(!isShift()||state.shiftRoundClearedV149||Number(state.shiftRoundMovesV149)!==2)return null;
    if(selectedPiece===null||!previewAnchor)return null;
    const shape=drag?.shape||state.tray?.[selectedPiece];
    if(!shape||!Core.canPlace(state.board,shape,previewAnchor.x,previewAnchor.y,state.size))return null;
    const sim=Core.simulatePlace(state.board,shape,previewAnchor.x,previewAnchor.y,'SHIFT',state.size);
    if(!sim)return null;
    if(Array.isArray(sim.waves)&&sim.waves.length)return {stable:true,plan:null};
    return {stable:false,...choosePack(sim.board,state.shiftPattern)};
  }

  updatePreview=function(){
    const out=previousUpdatePreview();
    const r=previewResult();
    if(r)showPlan(r.plan,r.stable);
    return out;
  };

  clearPreview=function(){
    const out=previousClearPreview();
    if(isShift())showPlan(state.shiftPattern,!!state.shiftRoundClearedV149);
    return out;
  };

  function nextPattern(prev){
    const pool=ALT.filter(p=>p!==prev);
    return pool[Math.floor(Math.random()*pool.length)]||'V_UP';
  }

  function resetRound(next){
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    state.shiftPackVersion=VERSION;
    state.shiftPattern=next;
    state.shiftAnchors=[];
    state.shiftAnchor=null;
    state.shiftAnchorHit=false;
    state.shiftStep=0;
    state.shiftMissionMoves=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    state.shiftEarly2V148=false;
  }

  /* Authoritative SHIFT round resolver for v1.5.2. Placement/scoring remains owned
     by v1.4.9; only the board transformation at round end changes. */
  completeTray=function(){
    if(!isShift())return previousCompleteTray();

    const preferred=ALT.includes(state.shiftPattern)?state.shiftPattern:'V_UP';

    if(state.shiftRoundClearedV149){
      state.shiftRoundResultV149='STABLE';
      requestSound('sequenceWin');
      boardEl.classList.remove('shift-stabilized-v131');void boardEl.offsetWidth;boardEl.classList.add('shift-stabilized-v131');
      setTimeout(()=>boardEl.classList.remove('shift-stabilized-v131'),440);
      announce('STABLE  •  NO SHIFT',true);
      pendingPackFx=null;
    }else{
      const result=choosePack(state.board,preferred);
      state.shiftRoundResultV149='SHIFT';
      state.shiftLastAppliedV152=result.plan;
      state.shiftLastKindV152=result.kind;
      state.board=result.board;
      pendingPackFx={moves:result.moves,plan:result.plan,kind:result.kind};
      boardEl.dataset.waveFx=result.plan;
      requestSound('shift');
      announce(result.kind==='pack'?'PACK SHIFT':'SHIFT',false);
      /* No line scan: choosePack rejects any compression that would complete a line. */
    }

    if(state.trayHadClear){
      state.chain++;
      const bonus=state.chain>=2?25*state.chain:0;
      if(bonus){
        state.score+=bonus;
        if(state.chain===3||state.chain===5||state.chain%10===0){announce(`CHAIN ${state.chain}  +${bonus}`,true);beep('chain');queueFx('chain',state.chain);}
      }
    }else state.chain=0;
    state.trayHadClear=false;

    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    resetRound(nextPattern(preferred));
  };

  function runPackFx(fx){
    if(!fx||!boardEl||!cellEls?.length)return;
    boardEl.classList.remove('shift-pack-board-v152');void boardEl.offsetWidth;boardEl.classList.add('shift-pack-board-v152');
    const moved=fx.moves.filter(m=>m.sx!==m.tx||m.sy!==m.ty);
    moved.forEach((m,i)=>{
      const target=cellEls[m.ty]?.[m.tx],source=cellEls[m.sy]?.[m.sx];
      if(!target||!source)return;
      const dx=source.offsetLeft-target.offsetLeft,dy=source.offsetTop-target.offsetTop;
      target.style.setProperty('--pack-x',`${dx}px`);
      target.style.setProperty('--pack-y',`${dy}px`);
      target.style.setProperty('--pack-delay',`${Math.min(80,(i%10)*7)}ms`);
      target.classList.remove('shift-pack-cell-v152');void target.offsetWidth;target.classList.add('shift-pack-cell-v152');
      setTimeout(()=>{
        target.classList.remove('shift-pack-cell-v152');
        target.style.removeProperty('--pack-x');target.style.removeProperty('--pack-y');target.style.removeProperty('--pack-delay');
      },520);
    });
    setTimeout(()=>{boardEl.classList.remove('shift-pack-board-v152');delete boardEl.dataset.waveFx;},540);
  }

  renderAll=function(){
    const out=previousRenderAll();
    if(pendingPackFx&&isShift()){
      const fx=pendingPackFx;pendingPackFx=null;
      requestAnimationFrame(()=>runPackFx(fx));
    }
    return out;
  };

  /* Selector preview: sparse rows visibly collapse all the way to opposite edges. */
  modeDemoHTML=function(id){
    if(id!=='SHIFT')return previousModeDemoHTML(id);
    let cells='';
    cells+=miniCell(0,1,'md-cyan v152-pack r-a p0');
    cells+=miniCell(2,1,'md-cyan v152-pack r-a p2');
    cells+=miniCell(4,1,'md-purple v152-pack r-a p4');
    cells+=miniCell(0,3,'md-green v152-pack r-b p0');
    cells+=miniCell(2,3,'md-green v152-pack r-b p2');
    cells+=miniCell(4,3,'md-gold v152-pack r-b p4');
    return `<div class="mode-demo mode-demo-v147 demo-shift-v152"><div class="mini-board">${cells}<div class="v149-demo-count"><i></i><i></i><i></i><b>→</b><strong>⇄</strong></div><em class="v152-pack-arrow ar">→</em><em class="v152-pack-arrow al">←</em></div></div>`;
  };

  queueMicrotask(()=>{
    try{buildMenu();renderMenu();if(isShift())showPlan(state.shiftPattern,!!state.shiftRoundClearedV149);}catch(_){ }
  });
})();


/* ===== hotfix-v155.js ===== */
/* GRID SHIFT v1.5.5 — authoritative SHIFT BUILD opening.
   v1.5.3/v1.5.4 may still be loaded underneath, but this layer bypasses their
   SHIFT placement and round resolution completely.
   - BUILD 1/2 and BUILD 2/2 are two real complete trays.
   - Both always end in PACK SHIFT.
   - From round 3 onward, CLEAR -> STABLE is active.
*/
(function(){
  'use strict';

  const VERSION=155;
  const BUILD_ROUNDS=2;
  const ALT=['V_UP','V_DOWN','H_LEFT','H_RIGHT'];
  const previousTryPlace=tryPlace;
  const previousCompleteTray=completeTray;
  const previousRenderAll=renderAll;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;
  const previousLoadSlot=loadSlot;
  const previousNewRun=newRun;
  let pendingPackFx=null;

  function isShift(){return state?.mode==='SHIFT'&&state?.shiftRulesVersion===149;}
  function buildRound(){return Math.max(0,Math.min(BUILD_ROUNDS,Number(state?.shiftBuildRoundV155)||0));}
  function inBuild(){return isShift()&&buildRound()<BUILD_ROUNDS;}

  function initBuild(forceFreshTray=false){
    if(!isShift())return;
    if(state.shiftBuildVersionV155===VERSION)return;
    state.shiftBuildVersionV155=VERSION;
    state.shiftBuildRoundV155=0;
    state.shiftLiveIntroV155=false;
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    state.shiftBuildActiveV153=false;
    if(forceFreshTray||!Array.isArray(state.tray)||state.tray.filter(Boolean).length!==3){
      state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    }
  }

  function cleanDirection(text){
    return String(text||'')
      .replace(/^BUILD(?: PHASE)?(?: \d\/\d)?\s*[•·-]?\s*/,'')
      .replace(/^CLEAR LINE = STABLE\s*•\s*/,'');
  }

  function syncUI(){
    const g=document.getElementById('shiftGuideV149');
    if(!g||!isShift())return;
    initBuild(false);

    const build=inBuild();
    const rule=g.querySelector('.shift-rule-v149');
    let label=g.querySelector('.shift-build-label-v153');
    if(!label&&rule){
      label=document.createElement('span');
      label.className='shift-build-label-v153';
      rule.insertBefore(label,rule.firstChild);
    }
    const strong=g.querySelector('.shift-rule-v149>strong');
    const dir=g.querySelector('.shift-direction-v149');

    g.classList.remove('build-v153','build-v154','first-live-v153','first-live-v154','build-v155','first-live-v155');

    if(build){
      g.classList.add('build-v155');
      g.classList.remove('stable-v149','last-move-v150','preview-stable-v150');
      boardEl?.classList.remove('shift-next-v150','shift-preview-stable-v150');
      if(label){label.hidden=false;label.textContent=`BUILD ${buildRound()+1}/${BUILD_ROUNDS}`;}
      if(strong)strong.textContent='PACK';
      if(dir){
        const base=cleanDirection(dir.textContent);
        dir.textContent=`BUILD  •  ${base}`;
      }
    }else{
      if(label)label.hidden=true;
      if(strong)strong.textContent='SHIFT';
      if(state.shiftLiveIntroV155){
        g.classList.add('first-live-v155');
        if(dir&&dir.textContent!=='NO SHIFT THIS ROUND'){
          const base=cleanDirection(dir.textContent);
          dir.textContent=`CLEAR LINE = STABLE  •  ${base}`;
        }
      }
    }
  }

  function empty(size){return Core.emptyBoard(size);}

  function packBoard(board,size,plan){
    const out=empty(size),moves=[];
    if(plan==='V_UP'||plan==='V_DOWN'){
      const firstUp=plan==='V_UP';
      for(let x=0;x<size;x++){
        const up=(x%2===0)?firstUp:!firstUp;
        const items=[];
        for(let y=0;y<size;y++)if(board[y][x])items.push({v:board[y][x],sx:x,sy:y});
        const start=up?0:size-items.length;
        items.forEach((it,i)=>{const ty=start+i;out[ty][x]=it.v;moves.push({sx:it.sx,sy:it.sy,tx:x,ty});});
      }
      return {board:out,moves,plan,kind:'pack'};
    }
    if(plan==='H_LEFT'||plan==='H_RIGHT'){
      const firstLeft=plan==='H_LEFT';
      for(let y=0;y<size;y++){
        const left=(y%2===0)?firstLeft:!firstLeft;
        const items=[];
        for(let x=0;x<size;x++)if(board[y][x])items.push({v:board[y][x],sx:x,sy:y});
        const start=left?0:size-items.length;
        items.forEach((it,i)=>{const tx=start+i;out[y][tx]=it.v;moves.push({sx:it.sx,sy:it.sy,tx,ty:y});});
      }
      return {board:out,moves,plan,kind:'pack'};
    }
    return null;
  }

  function uniformBoard(board,size,plan){
    const out=empty(size),moves=[];
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const v=board[y][x];if(!v)continue;
      let tx=x,ty=y;
      if(plan==='V_ALL_UP')ty=(y-1+size)%size;
      else if(plan==='V_ALL_DOWN')ty=(y+1)%size;
      else if(plan==='H_ALL_LEFT')tx=(x-1+size)%size;
      else if(plan==='H_ALL_RIGHT')tx=(x+1)%size;
      out[ty][tx]=v;moves.push({sx:x,sy:y,tx,ty});
    }
    return {board:out,moves,plan,kind:'fallback'};
  }

  function hasFullLine(board,size){
    for(let y=0;y<size;y++){
      let full=true;for(let x=0;x<size;x++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    for(let x=0;x<size;x++){
      let full=true;for(let y=0;y<size;y++)if(!board[y][x]){full=false;break;}
      if(full)return true;
    }
    return false;
  }

  function candidateOrder(preferred){
    const p=ALT.includes(preferred)?preferred:'V_UP';
    const opposite=p==='V_UP'?'V_DOWN':p==='V_DOWN'?'V_UP':p==='H_LEFT'?'H_RIGHT':'H_LEFT';
    const other=p.startsWith('V')?['H_LEFT','H_RIGHT']:['V_UP','V_DOWN'];
    return [p,opposite,...other];
  }

  function fallbackPlan(preferred){
    if(preferred==='V_DOWN')return 'V_ALL_DOWN';
    if(preferred==='H_LEFT')return 'H_ALL_LEFT';
    if(preferred==='H_RIGHT')return 'H_ALL_RIGHT';
    return 'V_ALL_UP';
  }

  function choosePack(board,preferred){
    for(const plan of candidateOrder(preferred)){
      const result=packBoard(board,state.size,plan);
      if(result&&!hasFullLine(result.board,state.size))return result;
    }
    return uniformBoard(board,state.size,fallbackPlan(preferred));
  }

  function nextPattern(prev){
    const pool=ALT.filter(p=>p!==prev);
    return pool[Math.floor(Math.random()*pool.length)]||'V_UP';
  }

  function resetRound(next){
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    state.shiftPattern=next;
    state.shiftAnchors=[];
    state.shiftAnchor=null;
    state.shiftAnchorHit=false;
    state.shiftStep=0;
    state.shiftMissionMoves=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    state.shiftEarly2V148=false;
  }

  function runPackFx(fx){
    if(!fx||!boardEl||!cellEls?.length)return;
    boardEl.classList.remove('shift-pack-board-v152');void boardEl.offsetWidth;boardEl.classList.add('shift-pack-board-v152');
    fx.moves.filter(m=>m.sx!==m.tx||m.sy!==m.ty).forEach((m,i)=>{
      const target=cellEls[m.ty]?.[m.tx],source=cellEls[m.sy]?.[m.sx];
      if(!target||!source)return;
      const dx=source.offsetLeft-target.offsetLeft,dy=source.offsetTop-target.offsetTop;
      target.style.setProperty('--pack-x',`${dx}px`);
      target.style.setProperty('--pack-y',`${dy}px`);
      target.style.setProperty('--pack-delay',`${Math.min(80,(i%10)*7)}ms`);
      target.classList.remove('shift-pack-cell-v152');void target.offsetWidth;target.classList.add('shift-pack-cell-v152');
      setTimeout(()=>{
        target.classList.remove('shift-pack-cell-v152');
        target.style.removeProperty('--pack-x');target.style.removeProperty('--pack-y');target.style.removeProperty('--pack-delay');
      },520);
    });
    setTimeout(()=>boardEl.classList.remove('shift-pack-board-v152'),540);
  }

  tryPlace=function(idx,x,y){
    if(!isShift())return previousTryPlace(idx,x,y);
    initBuild(false);
    if(state.gameOver||resolving)return false;

    const shape=state.tray[idx];
    if(!shape||!Core.canPlace(state.board,shape,x,y,state.size))return false;
    const sim=Core.simulatePlace(state.board,shape,x,y,'SHIFT',state.size);
    if(!sim)return false;

    const build=inBuild();
    state.board=sim.board;
    state.tray[idx]=null;
    state.moves++;
    state.shiftRoundMovesV149=Math.min(3,(Number(state.shiftRoundMovesV149)||0)+1);
    state.score+=shape.cells.length;
    state.lastPlaced=sim.placed.map(c=>c.slice());
    queueFx('placed',sim.placed);
    beep('place',shape.cells.length);

    let totalUnits=0,totalCells=0;
    sim.waves.forEach((wave,i)=>{totalUnits+=wave.units;totalCells+=wave.cells.length;queueFx('burst',{cells:wave.cells,wave:i});});
    if(totalUnits>0){
      if(!build)state.shiftRoundClearedV149=true;
      state.trayHadClear=true;
      const gain=scoreClear(totalUnits,totalCells,Math.max(0,sim.waves.length-1));
      state.score+=gain;
      announce(totalUnits>1?`${totalUnits} CLEAR  +${gain}`:`CLEAR  +${gain}`,totalUnits>1);
      beep(totalUnits>1?'multi':'clear');
    }

    if(state.tray.every(p=>p===null))completeTray();

    if(state.score>state.best)state.best=state.score;
    selectedPiece=null;previewAnchor=null;
    renderAll();scheduleSave();
    if(!state.gameOver&&!state.tray.some(p=>p&&Core.hasModePlacement(state.board,p,state.size,state.mode)))endGame('NO MOVES');
    return true;
  };

  completeTray=function(){
    if(!isShift())return previousCompleteTray();
    initBuild(false);
    const build=inBuild();
    const before=buildRound();
    const preferred=ALT.includes(state.shiftPattern)?state.shiftPattern:'V_UP';

    if(!build&&state.shiftRoundClearedV149){
      state.shiftRoundResultV149='STABLE';
      requestSound('sequenceWin');
      boardEl.classList.remove('shift-stabilized-v131');void boardEl.offsetWidth;boardEl.classList.add('shift-stabilized-v131');
      setTimeout(()=>boardEl.classList.remove('shift-stabilized-v131'),440);
      announce('STABLE  •  NO SHIFT',true);
      pendingPackFx=null;
    }else{
      const result=choosePack(state.board,preferred);
      state.shiftRoundResultV149='SHIFT';
      state.shiftLastAppliedV155=result.plan;
      state.board=result.board;
      pendingPackFx={moves:result.moves,plan:result.plan,kind:result.kind};
      requestSound('shift');
      announce(build?`BUILD ${before+1}/${BUILD_ROUNDS}  •  PACK`:(result.kind==='pack'?'PACK SHIFT':'SHIFT'),false);
    }

    if(state.trayHadClear){
      state.chain++;
      const bonus=state.chain>=2?25*state.chain:0;
      if(bonus){
        state.score+=bonus;
        if(state.chain===3||state.chain===5||state.chain%10===0){announce(`CHAIN ${state.chain}  +${bonus}`,true);beep('chain');queueFx('chain',state.chain);}
      }
    }else state.chain=0;
    state.trayHadClear=false;

    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    resetRound(nextPattern(preferred));

    if(build){
      state.shiftBuildRoundV155=Math.min(BUILD_ROUNDS,before+1);
      if(state.shiftBuildRoundV155>=BUILD_ROUNDS){
        state.shiftLiveIntroV155=true;
        announce('CLEAR LINE  →  STABLE',true);
      }
    }else if(state.shiftLiveIntroV155){
      state.shiftLiveIntroV155=false;
    }
  };

  renderAll=function(){
    const out=previousRenderAll();
    if(pendingPackFx&&isShift()){
      const fx=pendingPackFx;pendingPackFx=null;
      requestAnimationFrame(()=>runPackFx(fx));
    }
    syncUI();
    return out;
  };

  updatePreview=function(){const out=previousUpdatePreview();syncUI();return out;};
  clearPreview=function(){const out=previousClearPreview();syncUI();return out;};

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(isShift()){
      const upgrading=state.shiftBuildVersionV155!==VERSION;
      initBuild(upgrading);
      renderAll();scheduleSave(true);
    }
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(isShift()){
      state.shiftBuildVersionV155=VERSION;
      state.shiftBuildRoundV155=0;
      state.shiftLiveIntroV155=false;
      state.shiftRoundMovesV149=0;
      state.shiftRoundClearedV149=false;
      renderAll();scheduleSave(true);
    }
    return out;
  };

  queueMicrotask(()=>{
    try{
      if(isShift()){
        const upgrading=state.shiftBuildVersionV155!==VERSION;
        initBuild(upgrading);
        renderAll();scheduleSave(true);
      }
    }catch(_){ }
  });
})();


/* ===== hotfix-v157.js ===== */
/* GRID SHIFT v1.5.7 — BUILD means BUILD: no SHIFT for the first two trays.
   Rounds 1–2 exist only to put material on the board. After 6 placements,
   normal CLEAR -> STABLE / otherwise PACK SHIFT begins.
*/
(function(){
  'use strict';

  const VERSION=157;
  const BUILD_ROUNDS=2;
  const ALT=['V_UP','V_DOWN','H_LEFT','H_RIGHT'];
  const previousCompleteTray=completeTray;
  const previousRenderAll=renderAll;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;
  const previousLoadSlot=loadSlot;
  const previousNewRun=newRun;

  function isShift(){return state?.mode==='SHIFT'&&state?.shiftRulesVersion===149;}
  function round(){return Math.max(0,Math.min(BUILD_ROUNDS,Number(state?.shiftBuildRoundV155)||0));}
  function inBuild(){return isShift()&&round()<BUILD_ROUNDS;}
  function nextPattern(prev){
    const pool=ALT.filter(p=>p!==prev);
    return pool[Math.floor(Math.random()*pool.length)]||'V_UP';
  }

  function resetRoundState(){
    state.shiftRoundMovesV149=0;
    state.shiftRoundClearedV149=false;
    state.shiftRoundResultV149='';
    state.shiftAnchors=[];
    state.shiftAnchor=null;
    state.shiftAnchorHit=false;
    state.shiftStep=0;
    state.shiftMissionMoves=0;
    state.shiftMissionFailed=false;
    state.shiftRoundResolved=false;
    state.shiftOutcome='';
    state.shiftEarly2V148=false;
  }

  function resetBuildOnce(force=false){
    if(!isShift())return;
    if(!force&&state.shiftBuildFixVersionV157===VERSION)return;
    state.shiftBuildFixVersionV157=VERSION;
    state.shiftBuildVersionV155=155;
    state.shiftBuildRoundV155=0;
    state.shiftLiveIntroV155=false;
    resetRoundState();
    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
  }

  function syncBuildUI(){
    if(!isShift())return;
    const g=document.getElementById('shiftGuideV149');
    if(!g)return;
    const build=inBuild();
    g.classList.toggle('build-v157',build);
    if(!build)return;

    g.classList.remove('last-move-v150','preview-stable-v150','stable-v149','first-live-v155');
    boardEl?.classList.remove('shift-next-v150','shift-preview-stable-v150');

    let label=g.querySelector('.shift-build-label-v153');
    if(!label){
      const rule=g.querySelector('.shift-rule-v149');
      if(rule){
        label=document.createElement('span');
        label.className='shift-build-label-v153';
        rule.insertBefore(label,rule.firstChild);
      }
    }
    if(label){label.hidden=false;label.textContent=`BUILD ${round()+1}/${BUILD_ROUNDS}`;}
    const strong=g.querySelector('.shift-rule-v149>strong');
    if(strong)strong.textContent='NO SHIFT';
    const dir=g.querySelector('.shift-direction-v149');
    if(dir)dir.textContent='PLACE 3 PIECES';
  }

  /* During BUILD we deliberately do NOT call v1.5.2/v1.5.5's tray resolver,
     because that resolver performs PACK SHIFT. We only refill the tray and
     advance the opening counter. */
  completeTray=function(){
    if(!isShift()||!inBuild())return previousCompleteTray();

    const before=round();

    if(state.trayHadClear){
      state.chain++;
      const bonus=state.chain>=2?25*state.chain:0;
      if(bonus){
        state.score+=bonus;
        if(state.chain===3||state.chain===5||state.chain%10===0){
          announce(`CHAIN ${state.chain}  +${bonus}`,true);
          beep('chain');
          queueFx('chain',state.chain);
        }
      }
    }else state.chain=0;
    state.trayHadClear=false;

    const prevPattern=ALT.includes(state.shiftPattern)?state.shiftPattern:'V_UP';
    state.tray=Core.generateFairTray(state.board,'SHIFT',state.size,Math.random,state.moves);
    state.shiftPattern=nextPattern(prevPattern);
    state.shiftBuildRoundV155=Math.min(BUILD_ROUNDS,before+1);
    resetRoundState();

    if(state.shiftBuildRoundV155<BUILD_ROUNDS){
      announce('BUILD 2/2  •  NO SHIFT',false);
    }else{
      state.shiftLiveIntroV155=true;
      announce('CLEAR LINE  →  STABLE',true);
    }
  };

  renderAll=function(){
    const out=previousRenderAll();
    syncBuildUI();
    return out;
  };

  updatePreview=function(){
    const out=previousUpdatePreview();
    syncBuildUI();
    return out;
  };

  clearPreview=function(){
    const out=previousClearPreview();
    syncBuildUI();
    return out;
  };

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(isShift()){
      resetBuildOnce(false);
      renderAll();
      scheduleSave(true);
    }
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(isShift()){
      state.shiftBuildFixVersionV157=VERSION;
      state.shiftBuildVersionV155=155;
      state.shiftBuildRoundV155=0;
      state.shiftLiveIntroV155=false;
      resetRoundState();
      renderAll();
      scheduleSave(true);
    }
    return out;
  };

  queueMicrotask(()=>{
    try{
      if(isShift()){
        resetBuildOnce(false);
        renderAll();
        scheduleSave(true);
      }
    }catch(_){ }
  });
})();

